CREATE TABLE customers (
    customer_id INT,
    customer_name VARCHAR
);

CREATE TABLE orders (
    order_id INT,
    customer_id INT,
    order_date DATE
);

CREATE TABLE returns (
    return_id INT,
    order_id INT,
    customer_id INT
);

INSERT INTO customers VALUES
(1, 'Alice Smith'),
(2, 'Bob Jones'),
(3, 'Charlie Brown');

